#include "unity.h"
#include "header.h"
#include "helpers.h"

// Function prototypes to match source implementation
float calculate_ct(node **root);
float calculate_tat(node **root);

void setUp(void) { }
void tearDown(void) { }

void unit_test_calculate_tat_already_computed(void) {
    node *root = NULL;
    float result;
    float expected_avg;

    /* Build a process queue with pre-calculated completion times.
       Path condition: ptr->CT != 0 for the first node, so calculate_ct is NOT called.
       We need to call calculate_ct first to set CT values, then call calculate_tat.
    */
    int ids[] = {1, 2, 3};
    int ats[] = {0, 2, 4};
    int bts[] = {5, 3, 1};
    int priorities[] = {1, 2, 3};
    int size = 3;

    root = helper_build_process_queue(ids, ats, bts, priorities, size);
    TEST_ASSERT_NOT_NULL(root);

    /* First, compute completion times so that CT fields are non-zero */
    (void)calculate_ct(&root);

    /* Verify that the first node's CT is non-zero (path condition) */
    TEST_ASSERT_NOT_EQUAL_INT(0, root->CT);

    /* Now call calculate_tat - this should take path 2 (skip calculate_ct) */
    result = calculate_tat(&root);

    /* Expected TATs: CT - AT.
       Process 1: CT = 5, AT = 0 → TAT = 5
       Process 2: CT = 8, AT = 2 → TAT = 6
       Process 3: CT = 9, AT = 4 → TAT = 5
       Sum = 5 + 6 + 5 = 16
       Average = 16 / 3 ≈ 5.333333
    */
    expected_avg = 16.0f / 3.0f;
    TEST_ASSERT_FLOAT_WITHIN(0.001f, expected_avg, result);

    /* Also verify that TAT fields were updated */
    node *ptr = root;
    int i = 0;
    int expected_tats[] = {5, 6, 5};
    while (ptr != NULL) {
        TEST_ASSERT_EQUAL_INT(expected_tats[i], ptr->TAT);
        ptr = ptr->next;
        i++;
    }

    /* Cleanup */
    helper_cleanup_process_queue(&root);
    TEST_ASSERT_NULL(root);
}

